function registerProjectsApi(router::HTTP.Router, impl; path_prefix::String="", optional_middlewares...)
    HTTP.register!(router, "POST", path_prefix * "/organization/projects/{project_id}/archive", OpenAPI.Servers.middleware(impl, archive_project_read, archive_project_validate, archive_project_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/organization/projects", OpenAPI.Servers.middleware(impl, create_project_read, create_project_validate, create_project_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/organization/projects/{project_id}/service_accounts", OpenAPI.Servers.middleware(impl, create_project_service_account_read, create_project_service_account_validate, create_project_service_account_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/organization/projects/{project_id}/users", OpenAPI.Servers.middleware(impl, create_project_user_read, create_project_user_validate, create_project_user_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/organization/projects/{project_id}/api_keys/{key_id}", OpenAPI.Servers.middleware(impl, delete_project_api_key_read, delete_project_api_key_validate, delete_project_api_key_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/organization/projects/{project_id}/service_accounts/{service_account_id}", OpenAPI.Servers.middleware(impl, delete_project_service_account_read, delete_project_service_account_validate, delete_project_service_account_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/organization/projects/{project_id}/users/{user_id}", OpenAPI.Servers.middleware(impl, delete_project_user_read, delete_project_user_validate, delete_project_user_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/organization/projects/{project_id}/api_keys", OpenAPI.Servers.middleware(impl, list_project_api_keys_read, list_project_api_keys_validate, list_project_api_keys_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/organization/projects/{project_id}/rate_limits", OpenAPI.Servers.middleware(impl, list_project_rate_limits_read, list_project_rate_limits_validate, list_project_rate_limits_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/organization/projects/{project_id}/service_accounts", OpenAPI.Servers.middleware(impl, list_project_service_accounts_read, list_project_service_accounts_validate, list_project_service_accounts_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/organization/projects/{project_id}/users", OpenAPI.Servers.middleware(impl, list_project_users_read, list_project_users_validate, list_project_users_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/organization/projects", OpenAPI.Servers.middleware(impl, list_projects_read, list_projects_validate, list_projects_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/organization/projects/{project_id}", OpenAPI.Servers.middleware(impl, modify_project_read, modify_project_validate, modify_project_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/organization/projects/{project_id}/users/{user_id}", OpenAPI.Servers.middleware(impl, modify_project_user_read, modify_project_user_validate, modify_project_user_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/organization/projects/{project_id}", OpenAPI.Servers.middleware(impl, retrieve_project_read, retrieve_project_validate, retrieve_project_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/organization/projects/{project_id}/api_keys/{key_id}", OpenAPI.Servers.middleware(impl, retrieve_project_api_key_read, retrieve_project_api_key_validate, retrieve_project_api_key_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/organization/projects/{project_id}/service_accounts/{service_account_id}", OpenAPI.Servers.middleware(impl, retrieve_project_service_account_read, retrieve_project_service_account_validate, retrieve_project_service_account_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/organization/projects/{project_id}/users/{user_id}", OpenAPI.Servers.middleware(impl, retrieve_project_user_read, retrieve_project_user_validate, retrieve_project_user_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/organization/projects/{project_id}/rate_limits/{rate_limit_id}", OpenAPI.Servers.middleware(impl, update_project_rate_limits_read, update_project_rate_limits_validate, update_project_rate_limits_invoke; optional_middlewares...))
    return router
end
